-- Independent KOFIA schema, frozen from Main V122/V127/V128/V135/V144-V149.
-- No account, holding, model or briefing tables belong in this database.
CREATE TABLE "TB_CD_DTL" (
 "CD_GRP" VARCHAR(30) NOT NULL, "CD_KEY" VARCHAR(100) NOT NULL,
 "CD_NM" VARCHAR(200) NOT NULL, "DESC" TEXT, "DSP_ORD" INTEGER,
 "ACTV_YN" CHAR(1) NOT NULL DEFAULT 'Y', "REG_DT" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 "MOD_DT" TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("CD_GRP", "CD_KEY")
);
CREATE TABLE "TB_API_LOG" (
 "API_LOG_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "TRACE_ID" VARCHAR(100) NOT NULL, "API_GRP_CD" VARCHAR(30) NOT NULL,
 "API_NM" VARCHAR(150) NOT NULL, "HTTP_METHOD" VARCHAR(10), "REQ_URL" VARCHAR(2000),
 "REQ_PARAM" TEXT, "REQ_BODY" TEXT, "HTTP_STS_CD" INTEGER, "RSP_BODY" TEXT,
 "SUCC_YN" CHAR(1) NOT NULL, "ERR_CD" VARCHAR(100), "ERR_MSG" VARCHAR(2000),
 "ELAPSED_MS" BIGINT, "RETRY_CNT" INTEGER NOT NULL DEFAULT 0,
 "REQ_DTTM" TIMESTAMPTZ NOT NULL, "RSP_DTTM" TIMESTAMPTZ
);
CREATE INDEX "IX_COLLECTOR_API_LOG" ON "TB_API_LOG"("API_GRP_CD", "REQ_DTTM");
-- Source: V122__add_kofia_common_collection.sql
CREATE TABLE "TB_KOFIA_RAW_RSP" (
  "RAW_RSP_ID" UUID PRIMARY KEY,
  "JOB_ID" UUID,
  "DATASET_CD" VARCHAR(60) NOT NULL,
  "REQ_FROM_DT" DATE NOT NULL,
  "REQ_TO_DT" DATE NOT NULL,
  "HTTP_STS" INTEGER NOT NULL,
  "ROW_CNT" INTEGER NOT NULL DEFAULT 0,
  "RAW_HASH" VARCHAR(64) NOT NULL,
  "PAYLOAD" JSONB NOT NULL,
  "COLLECT_DTTM" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX "IX_KOFIA_RAW_RSP_DATASET_DT"
  ON "TB_KOFIA_RAW_RSP" ("DATASET_CD", "REQ_FROM_DT", "REQ_TO_DT");

CREATE TABLE "TB_KOFIA_DATA_ROW" (
  "DATASET_CD" VARCHAR(60) NOT NULL,
  "BASE_DT" DATE NOT NULL,
  "ROW_KEY" VARCHAR(200) NOT NULL,
  "PAYLOAD" JSONB NOT NULL,
  "RAW_HASH" VARCHAR(64) NOT NULL,
  "FIRST_COLLECT_DTTM" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "LAST_COLLECT_DTTM" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("DATASET_CD", "BASE_DT", "ROW_KEY")
);

CREATE TABLE "TB_KOFIA_CRDT_BAL_DAY" (
  "BASE_DT" DATE PRIMARY KEY,
  "CRDT_LOAN_TOT_AMT" NUMERIC(24, 4),
  "KOSPI_CRDT_LOAN_AMT" NUMERIC(24, 4),
  "KOSDAQ_CRDT_LOAN_AMT" NUMERIC(24, 4),
  "STK_LOAN_TOT_AMT" NUMERIC(24, 4),
  "KOSPI_STK_LOAN_AMT" NUMERIC(24, 4),
  "KOSDAQ_STK_LOAN_AMT" NUMERIC(24, 4),
  "ETC_STK_LOAN_AMT" NUMERIC(24, 4),
  "SECU_COLLATERAL_LOAN_AMT" NUMERIC(24, 4),
  "UNIT_CD" VARCHAR(20) NOT NULL DEFAULT 'MILLION_KRW',
  "DATA_SRC_CD" VARCHAR(20) NOT NULL DEFAULT 'KOFIA',
  "RAW_HASH" VARCHAR(64) NOT NULL,
  "DATA_STS" VARCHAR(20) NOT NULL DEFAULT 'FRESH',
  "COLLECT_DTTM" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "UPD_DTTM" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "TB_KOFIA_CLCT_JOB" (
  "JOB_ID" UUID PRIMARY KEY,
  "FROM_DT" DATE NOT NULL,
  "TO_DT" DATE NOT NULL,
  "DATASET_CDS" VARCHAR(1000) NOT NULL,
  "STS" VARCHAR(30) NOT NULL,
  "TOTAL_ITEM_CNT" INTEGER NOT NULL DEFAULT 0,
  "SUCCESS_ITEM_CNT" INTEGER NOT NULL DEFAULT 0,
  "FAILED_ITEM_CNT" INTEGER NOT NULL DEFAULT 0,
  "ERROR_MSG" VARCHAR(4000),
  "CRT_DTTM" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "START_DTTM" TIMESTAMP,
  "COMPLETE_DTTM" TIMESTAMP
);

CREATE UNIQUE INDEX "UX_KOFIA_CLCT_JOB_ACTIVE_RANGE"
  ON "TB_KOFIA_CLCT_JOB" ("FROM_DT", "TO_DT", "DATASET_CDS")
  WHERE "STS" IN ('QUEUED', 'RUNNING');

CREATE TABLE "TB_KOFIA_CLCT_JOB_ITEM" (
  "ITEM_ID" BIGSERIAL PRIMARY KEY,
  "JOB_ID" UUID NOT NULL REFERENCES "TB_KOFIA_CLCT_JOB"("JOB_ID") ON DELETE CASCADE,
  "DATASET_CD" VARCHAR(60) NOT NULL,
  "FROM_DT" DATE NOT NULL,
  "TO_DT" DATE NOT NULL,
  "STS" VARCHAR(30) NOT NULL DEFAULT 'PENDING',
  "RECEIVED_CNT" INTEGER NOT NULL DEFAULT 0,
  "STORED_CNT" INTEGER NOT NULL DEFAULT 0,
  "ERROR_MSG" VARCHAR(4000),
  "START_DTTM" TIMESTAMP,
  "COMPLETE_DTTM" TIMESTAMP,
  UNIQUE ("JOB_ID", "DATASET_CD", "FROM_DT", "TO_DT")
);

COMMENT ON TABLE "TB_KOFIA_RAW_RSP" IS 'KOFIA FreeSIS 원본 HTTP 응답';
COMMENT ON TABLE "TB_KOFIA_DATA_ROW" IS 'KOFIA Dataset별 원본 행';
COMMENT ON TABLE "TB_KOFIA_CRDT_BAL_DAY" IS '금융투자협회 신용공여 잔고 일별 정규화 데이터(금액 단위: 백만원)';
COMMENT ON TABLE "TB_KOFIA_CLCT_JOB" IS 'KOFIA 기간 수집 비동기 작업';
COMMENT ON TABLE "TB_KOFIA_CLCT_JOB_ITEM" IS 'KOFIA 기간 수집 Dataset 및 기간 조각별 실행 결과';

-- Source: V127__share_external_circuit_breaker_state.sql
CREATE TABLE "TB_EXT_CIRCUIT" (
  "CIRCUIT_KEY" VARCHAR(150) PRIMARY KEY,
  "STATE" VARCHAR(20) NOT NULL DEFAULT 'CLOSED',
  "FAILURE_CNT" INTEGER NOT NULL DEFAULT 0,
  "OPENED_AT" TIMESTAMP WITH TIME ZONE,
  "HALF_OPEN_IN_FLIGHT" BOOLEAN NOT NULL DEFAULT FALSE,
  "UPD_DTTM" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "CK_TB_EXT_CIRCUIT_01" CHECK ("STATE" IN ('CLOSED','OPEN','HALF_OPEN')),
  CONSTRAINT "CK_TB_EXT_CIRCUIT_02" CHECK ("FAILURE_CNT" >= 0)
);

COMMENT ON TABLE "TB_EXT_CIRCUIT" IS '외부 공급자 Circuit Breaker 다중 인스턴스 공유 상태';

-- Source: V135__add_kofia_service_catalog_and_market_metrics.sql
CREATE TABLE "TB_KOFIA_SVC" (
  "SERVICE_ID" VARCHAR(60) PRIMARY KEY,
  "SERVICE_NM" VARCHAR(300) NOT NULL,
  "MENU_PATH" VARCHAR(1000),
  "PARENT_DIV_ID" VARCHAR(60),
  "MENU_DIV_ID" VARCHAR(60),
  "OBJ_NM" VARCHAR(100),
  "OUTPUT_FORM_NO" VARCHAR(60),
  "OUTPUT_SQL_KEY" VARCHAR(300),
  "POPULARITY_VAL" BIGINT,
  "FAVORITE_ROW_SEQ" INTEGER,
  "HEADER_META" JSONB NOT NULL DEFAULT '[]'::jsonb,
  "SEARCH_META" JSONB NOT NULL DEFAULT '[]'::jsonb,
  "UNIT_META" JSONB NOT NULL DEFAULT '{}'::jsonb,
  "LATEST_DATE_META" JSONB NOT NULL DEFAULT '[]'::jsonb,
  "META_HASH" VARCHAR(64) NOT NULL,
  "NORMALIZE_YN" CHAR(1) NOT NULL DEFAULT 'N',
  "USE_YN" CHAR(1) NOT NULL DEFAULT 'Y',
  "LAST_DISCOVER_DTTM" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "CRT_DTTM" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "UPD_DTTM" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "CK_KOFIA_SVC_01" CHECK ("NORMALIZE_YN" IN ('Y','N')),
  CONSTRAINT "CK_KOFIA_SVC_02" CHECK ("USE_YN" IN ('Y','N'))
);

CREATE TABLE "TB_KOFIA_SVC_RANK_HIS" (
  "SNAPSHOT_DT" DATE NOT NULL,
  "SERVICE_ID" VARCHAR(60) NOT NULL REFERENCES "TB_KOFIA_SVC"("SERVICE_ID"),
  "ROW_SEQ" INTEGER NOT NULL,
  "POPULARITY_VAL" BIGINT,
  "COLLECT_DTTM" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("SNAPSHOT_DT", "SERVICE_ID")
);

ALTER TABLE "TB_KOFIA_DATA_ROW"
  ADD COLUMN "ROW_TYPE" VARCHAR(20) NOT NULL DEFAULT 'DATA',
  ADD COLUMN "ENTITY_CD" VARCHAR(100),
  ADD COLUMN "ENTITY_NM" VARCHAR(300),
  ADD COLUMN "METRIC_SCOPE_CD" VARCHAR(100),
  ADD COLUMN "REQ_PARAMS" JSONB,
  ADD CONSTRAINT "CK_KOFIA_DATA_ROW_01"
    CHECK ("ROW_TYPE" IN ('DATA','TOTAL','AVERAGE','SUBTOTAL','OTHER'));

CREATE TABLE "TB_KOFIA_SEC_LEND_DAY" (
  "BASE_DT" DATE NOT NULL,
  "ITEM_CD" VARCHAR(40) NOT NULL,
  "ITEM_NM" VARCHAR(200) NOT NULL,
  "CONTRACT_QTY" NUMERIC(24,0),
  "REPAY_QTY" NUMERIC(24,0),
  "BALANCE_QTY" NUMERIC(24,0),
  "BALANCE_MKT_AMT" NUMERIC(24,4),
  "AMT_UNIT_CD" VARCHAR(20) NOT NULL DEFAULT 'MILLION_KRW',
  "DATA_SRC_CD" VARCHAR(20) NOT NULL DEFAULT 'KOFIA',
  "RAW_HASH" VARCHAR(64) NOT NULL,
  "DATA_STS" VARCHAR(20) NOT NULL DEFAULT 'FRESH',
  "COLLECT_DTTM" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "UPD_DTTM" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("BASE_DT", "ITEM_CD"),
  CONSTRAINT "CK_KOFIA_SEC_LEND_01" CHECK ("DATA_STS" IN ('FRESH','STALE','MISSING','PARTIAL','ERROR'))
);

CREATE TABLE "TB_KOFIA_MKT_FUND_DAY" (
  "BASE_DT" DATE PRIMARY KEY,
  "INVESTOR_DEPOSIT_AMT" NUMERIC(24,4),
  "DERIV_DEPOSIT_AMT" NUMERIC(24,4),
  "CUSTOMER_RP_BALANCE_AMT" NUMERIC(24,4),
  "RECEIVABLE_AMT" NUMERIC(24,4),
  "FORCED_LIQUIDATION_AMT" NUMERIC(24,4),
  "FORCED_LIQUIDATION_RT" NUMERIC(12,6),
  "UNIT_CD" VARCHAR(20) NOT NULL DEFAULT 'MILLION_KRW',
  "DATA_SRC_CD" VARCHAR(20) NOT NULL DEFAULT 'KOFIA',
  "RAW_HASH" VARCHAR(64) NOT NULL,
  "DATA_STS" VARCHAR(20) NOT NULL DEFAULT 'FRESH',
  "COLLECT_DTTM" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "UPD_DTTM" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "CK_KOFIA_MKT_FUND_01" CHECK ("DATA_STS" IN ('FRESH','STALE','MISSING','PARTIAL','ERROR'))
);

COMMENT ON TABLE "TB_KOFIA_SVC" IS 'FreeSIS 즐겨찾는 통계 서비스 및 실행 메타데이터 카탈로그';
COMMENT ON TABLE "TB_KOFIA_SVC_RANK_HIS" IS 'FreeSIS 즐겨찾는 통계 일별 순위 스냅샷';
COMMENT ON TABLE "TB_KOFIA_SEC_LEND_DAY" IS '금융투자협회 대차거래 일별 정규화 데이터';
COMMENT ON TABLE "TB_KOFIA_MKT_FUND_DAY" IS '금융투자협회 증시자금 일별 정규화 데이터';

-- Source: V144__add_kofia_lookup_reference_data.sql
